    private static readonly SignatureAlgorithm Algorithm = SignatureAlgorithm.Ed25519;

    public static LicensePayload Payload(
        int version = 2,
        string? fingerprint = null,
        DateOnly? expiry = null,
        string? licensedTo = "Test School",
        DateOnly? issuedAt = null,
        DateOnly? notBefore = null,
        string keyId = LicensePayload.DefaultKeyId) =>
        new(
            version,
            fingerprint ?? Fingerprint,
            expiry ?? new DateOnly(2027, 6, 30),
            licensedTo,
            issuedAt ?? new DateOnly(2026, 1, 1),
            notBefore,
            keyId);

    public static string Sign(LicensePayload payload, byte[]? privateKey = null) =>
        SignJson(payload.WriteCanonicalJson(), privateKey);

    public static string SignJson(string json, byte[]? privateKey = null)
    {
        using var key = Key.Import(
            Algorithm,
            privateKey ?? PrivateKey,
            KeyBlobFormat.RawPrivateKey);
        var signature = Algorithm.Sign(key, Encoding.UTF8.GetBytes(json));
        return LicenseEnvelope.Encode(json, signature);
    }

    public static LicenseVerifier Verifier() => new(PublicKey);

    public static DateTime Utc(int year, int month, int day, int hour = 12, int minute = 0) =>
        new(year, month, day, hour, minute, 0, DateTimeKind.Utc);

    public static DateOnly Date(int year, int month, int day) => new(year, month, day);
