internal sealed class FakeLicenseStorage : ILicenseStorage
{
    public string? Text { get; set; }

    public int Writes { get; private set; }

    public int Clears { get; private set; }

    public string? Read() => Text;

    public void Write(string licenseText)
    {
        Writes++;
        Text = licenseText;
    }

    public void Clear()
    {
        Clears++;
        Text = null;
    }
}

internal sealed class FakeTrustedTimeStorage : ITrustedTimeStorage
{
    public TrustedTimeRecord? Record { get; set; }

    public int Writes { get; private set; }

    public int Clears { get; private set; }

    public TrustedTimeRecord? Read() => Record;

    public void Write(TrustedTimeRecord record)
    {
        Writes++;
        Record = record;
    }

    public void Clear()
    {
        Clears++;
        Record = null;
    }
}

internal sealed class FakeFingerprintSource : IDeviceFingerprintSource
{
    public FakeFingerprintSource(
        string hash = LicenseTestKit.Fingerprint,
        bool isStrong = true,
        bool usedFallback = false)
    {
        Fingerprint = new DeviceFingerprint(hash, isStrong, usedFallback);
    }

    public DeviceFingerprint Fingerprint { get; }

    public int Calls { get; private set; }

    public Task<DeviceFingerprint> GetFingerprintAsync(CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        Calls++;
        return Task.FromResult(Fingerprint);
    }
}

internal sealed class FakeLocalClock : ILocalClock
{
    public FakeLocalClock(DateTime utcNow, DateTime? localNow = null)
    {
        UtcNow = DateTime.SpecifyKind(utcNow, DateTimeKind.Utc);
        LocalNow = localNow is { } local
            ? DateTime.SpecifyKind(local, DateTimeKind.Unspecified)
            : DateTime.SpecifyKind(utcNow, DateTimeKind.Unspecified);
    }

    public DateTime UtcNow { get; set; }

    public DateTime LocalNow { get; set; }
}
